INSERT INTO `product` VALUES (1,1,'Hoodie',1500,1,2,'data:image/jpeg;base64,',48,'This hoodie set front view black and grey hoodie photo is taken by professional photographers which captures the beauty with nature colors and clean composition. ',1,'2026-02-08 16:22:04','2026-03-20 13:31:13'),(2,1,'Full hand T-shirt',1000,1,3,'data:image/jpeg;base64,',25,'Color variation from images shown above is expected , as each piece is processed with hand , so a bit of variation is expected ',1,'2026-02-08 16:35:26','2026-02-10 13:00:12'),(3,2,'Tomato',25,1,1,'data:image/jpeg;base64,',996,'Tomato is an herbaceous annual in the family Solanaceae grown for its edible fruit. The plant can be erect with short stems or vine-like with long, spreading stems.',1,'2026-02-08 17:16:28','2026-03-14 08:43:38'),(4,2,'carrot',15,1,1,'data:image/png;base64,',989,'The carrot (Daucus carota) is a popular, crunchy root vegetable, usually orange, featuring a long, tapered taproot that grows underground.',1,'2026-02-08 17:27:14','2026-03-14 08:01:47'),(5,2,'onion',25,1,1,'data:image/jpeg;base64,',997,'Good source of manganese, copper, Vitamin B6, Vitamin C and Dietary Fibers,Can be used in curries, snacks and salads',1,'2026-02-08 17:33:03','2026-03-14 06:35:34'),(6,3,'Sambar rice',50,1,2,'data:image/jpeg;base64,',100,'A one-pot delight of aromatic royal Ponni rice simmered in a delectable lentil and vegetable stew, called Sambar in Southern India.',1,'2026-02-08 17:37:21','2026-03-20 13:28:18'),(7,4,'Apple',100,1,2,'data:image/jpeg;base64,',100,'An apple is the round, edible, and nutrient-dense pome fruit originating in Central Asia and cultivated worldwide for its crisp texture and sweet or tart flavor',1,'2026-02-09 04:16:00','2026-03-20 13:28:50'),(8,5,'Short kurti',300,1,3,'data:image/jpeg;base64,',50,' This short kurti has been designed keeping in mind the latest trends in contemporary casual fashion and cool colors for summers. ',1,'2026-02-10 13:08:48','2026-03-20 13:29:56'),(9,5,'Lehenga',10500,1,5,'data:image/jpeg;base64,',10,'This captivating masterpiece, set on a net base in deep, rich hues, reimagines Rajasthani art and culture through a contemporary lens.',1,'2026-02-14 09:38:12','2026-03-20 13:32:10'),(10,2,'Brinjal',35,1,2,'data:image/jpeg;base64,',999,'Brinjal, also known  is a highly nutritious, low-calorie, fiber-rich berry from the nightshade family, commonly used as a vegetable in worldwide cuisines',1,'2026-02-19 13:41:42','2026-03-14 06:35:34'),(11,2,'Potato',30,1,3,'data:image/webp;base64,',467,'Fresh potatoes are a versatile, nutrient-dense, and widely consumed root vegetable, featuring a starchy, edible tuber that serves as a staple in global cuisines. ',1,'2026-02-19 14:21:39','2026-03-20 13:32:36'),(12,3,'Ladies finger',35,1,3,'data:image/webp;base64,',299,'It is characterized by its slender, elongated, and tapered green pods that are slightly ridged',1,'2026-02-19 14:26:06','2026-03-20 13:32:58'),(13,6,' Spicy Sambar Masala',20,1,4,'data:image/jpeg;base64,',100,'It features a fiery kick from increased dried red chillies mixed with roasted lentils, coriander, cumin, and fenugreek, offering a deep, earthy flavour.',1,'2026-02-19 14:36:26','2026-03-20 13:33:37'),(14,7,'Bone less Chicken',250,1,3,'data:image/jpeg;base64,',2000,'Boneless chicken refers to poultry meat, most commonly the breast or thigh, that has had the bones removed for easier preparation and consumption. ',1,'2026-02-19 14:40:13','2026-03-20 13:33:56'),(15,7,'Fish Slices',400,1,4,'data:image/jpeg;base64,',39,'Immunity & Vision: Vitamins A & D, plus selenium, boost immune function and maintain healthy eyesight',1,'2026-02-19 14:45:07','2026-03-20 13:34:29'),(16,7,'Mutton',500,1,4,'data:image/jpeg;base64,',400,'Fresh, tender goat mutton is available for doorstep delivery, often within 120 minutes, featuring options like premium curry cuts, chops, and boneless meat. ',1,'2026-02-19 14:49:18','2026-03-20 13:34:43');
