INSERT INTO `store` VALUES (1,'Dominos','12,21,k, Tambaram, Chennai.','09:00:00','20:00:00','data:image/jpeg;base64,',1,83423,34348,'Domino\'s is a leading global pizza delivery and carryout chain, known for its commitment to quality, innovation, and community involvement.','dominos@gmail.com',2,'2026-02-08 15:53:25','2026-02-08 15:53:25'),(2,'kamalas VEG Restaurant','3/88 , Vandalur salai,near zoo','09:00:00','20:00:00','data:image/jpeg;base64,',1,43088,8,'Based on search results, there are multiple \"Kamala\" branded vegetarian eateries, with the most prominent being Kamal Pure Vegetarian in Chadayamangalam, Kollam (Kerala) and a formerly active Kamal\'s Veg Restaurant in Esplanade, Kolkata. They typically offer South Indian, North Indian, and Chinese vegetarian cuisine, with options for takeout and dining','sathaya@gmail.com',8,'2026-02-19 15:19:48','2026-02-19 15:19:48');
